export const visualContractTemplateKeys = [
  "newsroom-pro",
  "edulaunch",
  "medica-clinic",
  "atelier-mode",
  "table-flame",
  "habitat-property",
  "studio-north",
  "neon-foundry",
  "pulse-saas",
  "campus-living",
] as const;

export type VisualContractTemplateKey = (typeof visualContractTemplateKeys)[number];

const contractKeys = new Set<string>(visualContractTemplateKeys);

const esc = (value: unknown) => String(value ?? "")
  .replaceAll("&", "&amp;")
  .replaceAll("<", "&lt;")
  .replaceAll(">", "&gt;")
  .replaceAll('"', "&quot;")
  .replaceAll("'", "&#039;");

const arr = (value: readonly string[] | undefined, fallback: string[]) => {
  const clean = (value || []).map(String).map((item) => item.trim()).filter(Boolean);
  return clean.length ? clean : fallback;
};

const slotUrl = (draft: WebsiteStudioDraft, index: number) => index === -1
  ? draft.site.heroImageUrl
  : draft.site.gallery[index] || "";

function media(draft: WebsiteStudioDraft, index: number, className: string, label: string) {
  const url = slotUrl(draft, index);
  return url
    ? `<div class="${className} media-slot"><img src="${esc(url)}" alt="${esc(label)}" loading="${index === -1 ? "eager" : "lazy"}"/></div>`
    : `<div class="${className} media-slot media-empty" data-media-slot="${index === -1 ? "hero" : `gallery-${index + 1}`}"><span>${esc(label)}</span><small>Replace image in Website Studio</small></div>`;
}

function logo(draft: WebsiteStudioDraft, className = "vc-logo") {
  return draft.brand.logoUrl
    ? `<span class="${className}"><img src="${esc(draft.brand.logoUrl)}" alt="${esc(draft.businessName)}"/></span>`
    : `<span class="${className} vc-logo-text">${esc(draft.brand.logoText || draft.businessName)}</span>`;
}

function button(label: string, href = "#primary-action", secondary = false) {
  return `<a class="vc-button${secondary ? " secondary" : ""}" href="${href}">${esc(label)}</a>`;
}

function newsRoom(draft: WebsiteStudioDraft) {
  const stories = arr(draft.site.services, ["Court ruling could reshape voting rights protections", "Extreme heat strains grid as climate risks intensify", "Rural hospitals face a tough road ahead", "Inside the debate over AI in the classroom"]);
  const latest = arr(draft.site.testimonials, ["Trade slowdown worries businesses and workers", "New energy incentives aim to cut costs, boost jobs", "Displacement climbs as conflict enters third year"]);
  const stats = draft.site.stats.length ? draft.site.stats : [{ value: "23M+", label: "Readers reached across platforms" }, { value: "120+", label: "In-depth stories published this year" }, { value: "50", label: "States and countries where we're read" }];
  return `<div class="vc vc-newsroom">
    <div class="news-utility"><div class="vc-shell"><span>Independent journalism. In the public interest.</span><nav><a>About</a><a>Our Impact</a><a>Contact</a><a>Support Us</a><b>Donate</b></nav></div></div>
    <header class="news-header vc-shell">${logo(draft)}<nav><a>Politics</a><a>Policy</a><a>Economy</a><a>Justice</a><a>Environment</a><a>Health</a><a>Education</a><a>World</a></nav><span class="search-mark">⌕</span></header>
    <main>
      <section class="vc-shell news-lead-grid">
        <article class="news-feature">${media(draft,-1,"news-feature-media",draft.site.headline)}<div class="news-feature-copy"><span>POLITICS</span><h1>${esc(draft.site.headline)}</h1><p>${esc(draft.site.tagline)}</p><small>By Editorial Desk · 2h ago</small></div></article>
        <aside class="news-sidebar"><h2>Featured Stories</h2>${stories.slice(0,4).map((story,index)=>`<article><div><span>${["JUSTICE","ENVIRONMENT","HEALTH","EDUCATION"][index]}</span><h3>${esc(story)}</h3><small>By Newsroom · ${index + 3}h ago</small></div>${media(draft,index,`news-thumb`,story)}</article>`).join("")}</aside>
      </section>
      <section class="vc-shell news-latest"><h2>Latest News</h2><div>${latest.slice(0,3).map((story,index)=>`<article>${media(draft,index+4,"news-card-media",story)}<span>${["ECONOMY","POLICY","WORLD"][index]}</span><h3>${esc(story)}</h3><small>By Newsroom · ${index * 2 + 2}h ago</small></article>`).join("")}</div></section>
      <section class="news-impact"><div class="vc-shell"><div><h2>Our Impact</h2><p>${esc(draft.site.description)}</p><a>See our impact →</a></div>${stats.slice(0,3).map((item)=>`<article><strong>${esc(item.value)}</strong><span>${esc(item.label)}</span></article>`).join("")}</div></section>
    </main>
    <footer class="news-footer"><div class="vc-shell"><div>${logo(draft)}<p>Independent journalism.<br/>In the public interest.</p></div><div><strong>Sections</strong><span>Politics · Policy · Economy · Justice</span></div><div><strong>Resources</strong><span>About Us · Our Impact · Newsletters</span></div><div><strong>Contact</strong><span>${esc(draft.contact.email)}<br/>${esc(draft.contact.phone)}</span></div></div></footer>
  </div>`;
}

