const renderers: Record<VisualContractTemplateKey, (draft: WebsiteStudioDraft) => string> = {
  "newsroom-pro": newsRoom,
  edulaunch: eduLaunch,
  "medica-clinic": medica,
  "atelier-mode": atelier,
  "table-flame": tableFlame,
  "habitat-property": habitat,
  "studio-north": studioNorth,
  "neon-foundry": neonFoundry,
  "pulse-saas": pulseSaas,
  "campus-living": campusLiving,
};

export function hasVisualContract(input: Pick<WebsiteStudioDraft,"templateKey"> | string): boolean {
  const key = typeof input === "string" ? input : String(input.templateKey || "");
  return contractKeys.has(key);
}

export function renderVisualContractShell(draft: WebsiteStudioDraft): string | null {
  const key = String(draft.templateKey || "");
  if (!hasVisualContract(key)) return null;
  return renderers[key as VisualContractTemplateKey](draft);
}

function fallbackShell(draft: WebsiteStudioDraft) {
  const family = getStructuralFamily(draft);
  const brand = draft.brand.logoUrl
    ? `<img src="${esc(draft.brand.logoUrl)}" alt="${esc(draft.businessName)}"/>`
    : `<strong>${esc(draft.brand.logoText || draft.businessName)}</strong>`;
  const announcement = draft.site.showAnnouncement ? `<div class="announcement">${esc(draft.site.announcement)}</div>` : "";
  return `<div class="site family-root family-${family}">${announcement}<header class="family-nav"><div class="shell"><a class="logo" href="#top">${brand}</a><nav><a href="#explore">Explore</a><a href="#primary-action">Contact</a></nav><a class="button primary" href="#primary-action">${esc(draft.site.primaryCta)}</a></div></header><main id="top">${renderStructuralBody(draft)}</main><footer><div class="shell"><strong>${esc(draft.businessName)}</strong><span>Built with Start To Up Website Studio · ${esc(structuralFamilyLabels[family])}</span></div></footer></div>`;
}

export function renderWebsiteStudioShell(draft: WebsiteStudioDraft): string {
  return renderVisualContractShell(draft) || fallbackShell(draft);
}

export function renderWebsiteStudioHtml(draft: WebsiteStudioDraft): string {
  return `<!doctype html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width, initial-scale=1.0"/><title>${esc(draft.seo.title)}</title><meta name="description" content="${esc(draft.seo.description)}"/><style>${websiteStudioCss(draft)}</style></head><body>${renderWebsiteStudioShell(draft)}</body></html>`;
}

